function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', W1 = '#3d2814', W2 = '#8b5a2b', W3 = '#c4a06a';
  const B1 = '#c4b898', B2 = '#e8dcc0', B3 = '#6a6358';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(10, 28, 14, 10, O); px(12, 30, 10, 6, W2);
  px(12, 30, 10, 2, W3); px(12, 34, 10, 2, W1);
  for (let i = 0; i < 34; i++) {
    const bx = 22 + i, by = 30 - Math.floor(i * 0.35);
    px(bx, by, 2, 6, O); px(bx + 1, by + 1, 1, 4, B2);
    if (i < 8) px(bx + 1, by + 1, 1, 2, B3);
  }
  px(52, 14, 6, 6, O); px(53, 15, 4, 4, B2);
  px(54, 15, 2, 2, B3);
}
